pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000000, "Test", "TST"); }
    function testFuzz_property(uint256 burnAmount) public {
        uint256 ownerBalance = c.balanceOf(address(this));
        vm.assume(burnAmount <= ownerBalance);
        vm.assume(burnAmount > 0);

        uint256 expectedTotalSupply = c.totalSupply() - burnAmount;

        c.burn(burnAmount);

        assertTrue(c.totalSupply() == c.balanceOf(address(this)));
    }
}
